def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separates the given string into a list of strings, where each string represents a separate group of nested parentheses.
    The function assumes that each group is balanced and not nested within each other, and ignores any spaces in the input string.
    :param paren_string: A string containing multiple groups of nested parentheses.
    :return: A list of strings, where each string represents a separate group of nested parentheses.
    """
    groups = []
    group = ""
    stack = 0
    for char in paren_string:
        if char == "(":
            stack += 1
        elif char == ")":
            stack -= 1
        if stack == 0 and char == ")":
            groups.append(group)
            group = ""
        else:
            group += char
    if group:
        groups.append(group)
    return groups

